(function(){'use strict';var f=document.getElementsByClassName('ngg-image-search-form');for(var i=0;i<f.length;i++){f[i].addEventListener('submit',function(e){e.preventDefault();var t=this.getElementsByClassName('ngg-image-search-input')[0];if(!t||!this.dataset.submissionUrl){return;}window.location=this.dataset.submissionUrl.replace('ngg-search-placeholder',encodeURIComponent(t.value));});}})();
